"""Independent acceptance/patch receipts. --validate runs the direct control's root checks."""
from pathlib import Path
import hashlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import time
from report_helpers import parse_acceptance, parse_test_summaries

root = Path(sys.argv[1]).resolve()
name = sys.argv[2]
manifest = json.loads((root / 'manifest.json').read_text())
assert name in manifest['runOrder']
case = root / name
repo = case / 'repo'
worker, kind, repetition = name.split('-')
environment = {**os.environ, 'PATH': str(case / 'bin') + os.pathsep + os.environ['PATH'], 'BENCH_CASE_DIR': str(case), 'BENCH_PACKAGE_ENTRY': manifest['packageEntry'], 'NEXT_TELEMETRY_DISABLED': '1'}
for command, executable in manifest['realExecutables'].items(): environment['BENCH_REAL_' + command.upper()] = executable

def run(label, command, cwd=repo):
    started = time.monotonic()
    timed_out = False
    with (case / (label + '.log')).open('w') as log:
        child = subprocess.Popen(command, cwd=cwd, env=environment, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
        try: code = child.wait(timeout=120)
        except subprocess.TimeoutExpired:
            timed_out = True
            os.killpg(child.pid, signal.SIGTERM)
            try: code = child.wait(timeout=3)
            except subprocess.TimeoutExpired:
                os.killpg(child.pid, signal.SIGKILL)
                code = child.wait()
    result = {'command': command, 'exitCode': code, 'timedOut': timed_out, 'durationMs': round((time.monotonic() - started) * 1000), 'log': label + '.log'}
    print(json.dumps({'case': name, 'check': label, **result}), flush=True)
    return result

def counts(path):
    if not path.is_file(): return {}
    data = json.loads(path.read_text())
    return {key: data[key] for key in ['numTotalTests', 'numPassedTests', 'numFailedTests', 'numPendingTests']}

def trace_rows():
    return [json.loads(line) for trace in sorted((repo / 'traces').glob('*.jsonl')) for line in trace.read_text().splitlines() if line.strip()]

verification_path = case / 'verification.json'
if not verification_path.exists():
    verification = {'independentRootChecks': [], 'supplementalRootChecks': []}
    if '--validate' in sys.argv:
        assert kind == 'standalone'
        for script in ['test', 'typecheck', 'lint', 'build']:
            result = run('independent-' + script, ['pnpm', 'run', script])
            result['script'] = script
            verification['independentRootChecks'].append(result)
            verification_path.write_text(json.dumps(verification, indent=2) + '\n')
    if '--validate-remaining' in sys.argv:
        assert kind == 'jev' and (case / 'timings.json').exists(), 'Supplemental checks require an already terminated loop.'
        attempted = {row['toolInput']['script'] for row in trace_rows() if (row.get('toolResult') or {}).get('action') == 'RUN_TESTS'}
        for script in ['test', 'typecheck', 'lint', 'build']:
            if script in attempted: continue
            result = run('supplemental-' + script, ['pnpm', 'run', script])
            result.update({'script': script, 'includedInCliMetrics': False})
            verification['supplementalRootChecks'].append(result)
            verification_path.write_text(json.dumps(verification, indent=2) + '\n')
    test = repo / 'apps/web/lib/format.test.ts'
    if test.is_file():
        report = case / 'format-tests.json'
        verification['formatTests'] = run('format-tests', ['pnpm', '--filter', 'web', 'exec', 'vitest', 'run', 'lib/format.test.ts', '--reporter=json', '--outputFile=' + str(report)])
        verification['formatTests']['counts'] = counts(report)
        regression = case / 'regression-web'
        (regression / 'lib').mkdir(parents=True)
        web = repo / 'apps/web'
        for filename in ['vitest.config.ts', 'vitest.setup.ts', 'vitest.d.ts', 'package.json']:
            shutil.copyfile(web / filename, regression / filename)
        shutil.copyfile(test, regression / 'lib/format.test.ts')
        (regression / 'lib/format.ts').write_bytes(subprocess.check_output(['git', 'show', 'HEAD:apps/web/lib/format.ts'], cwd=repo))
        (regression / 'node_modules').symlink_to(web / 'node_modules', target_is_directory=True)
        regression_report = regression / 'tests.json'
        verification['baselineRegression'] = run('baseline-regression', ['node', str(web / 'node_modules/vitest/vitest.mjs'), 'run', 'lib/format.test.ts', '--reporter=json', '--outputFile=' + str(regression_report)], regression)
        verification['baselineRegression']['counts'] = counts(regression_report)
        if regression_report.exists():
            data = json.loads(regression_report.read_text())
            verification['baselineRegression']['failedTitles'] = [assertion['fullName'] for suite in data['testResults'] for assertion in suite['assertionResults'] if assertion['status'] == 'failed']
    probe = case / 'acceptance-probe.mjs'
    probe.write_text('''import { pathToFileURL } from 'node:url';
const { truncateAddress } = await import(pathToFileURL(process.argv[2]));
const fixture = 'GACR43EX3GKZWQEHHTM6XPBSKBJLHNZPJFXZFXMFXSTF34OCDSNZHWGB';
const examples = [['empty', '', ''], ['undefined', undefined, ''], ['null', null, '']];
for (let length = 1; length <= 10; length++) { const text = 'ABCDEFGHIJ'.slice(0, length); examples.push(['length-' + length, text, text]); }
examples.push(['length-11', 'ABCDEFGHIJK', 'ABCDEF...HIJK'], ['stellar-address-56', fixture, 'GACR43...HWGB']);
const results = examples.map(([name, input, expected]) => { const actual = truncateAddress(input); return { name, expected, actual, passed: actual === expected }; });
console.log(JSON.stringify({ fixtureLength: fixture.length, passed: results.every((result) => result.passed), results }));
process.exitCode = results.every((result) => result.passed) ? 0 : 1;
''')
    verification['acceptanceProbe'] = run('acceptance', ['node', str(probe), str(repo / 'apps/web/lib/format.ts')])
    try: verification['acceptanceProbe']['results'] = json.loads((case / 'acceptance.log').read_text())
    except ValueError: verification['acceptanceProbe']['results'] = {'passed': False}
    verification_path.write_text(json.dumps(verification, indent=2) + '\n')
else:
    verification = json.loads(verification_path.read_text())

# Node may append a module-format warning to the combined stdout/stderr log.
# Parse the probe's own JSON line; keep the complete diagnostic log unchanged.
try:
    verification['acceptanceProbe']['results'] = parse_acceptance((case / 'acceptance.log').read_text())
except ValueError:
    verification['acceptanceProbe']['results'] = {'passed': False}
verification_path.write_text(json.dumps(verification, indent=2) + '\n')

initial = json.loads((case / 'target-before.json').read_text())
tracked = subprocess.check_output(['git', 'ls-files', '-z'], cwd=repo).decode().split('\0')
files = {filename: hashlib.sha256((repo / filename).read_bytes()).hexdigest() for filename in tracked if filename and (repo / filename).is_file()}
changed = {filename for filename in set(files) | set(initial['files']) if files.get(filename) != initial['files'].get(filename)}
if (repo / 'apps/web/lib/format.test.ts').exists(): changed.add('apps/web/lib/format.test.ts')
status = subprocess.check_output(['git', 'status', '--porcelain'], cwd=repo, text=True)
untracked = {line[3:] for line in status.splitlines() if line.startswith('?? ')}
patch = subprocess.check_output(['git', 'diff', 'HEAD', '--binary'], cwd=repo)
if (repo / 'apps/web/lib/format.test.ts').exists():
    added = subprocess.run(['git', 'diff', '--no-index', '--binary', '--', '/dev/null', 'apps/web/lib/format.test.ts'], cwd=repo, capture_output=True)
    if added.returncode == 1: patch += added.stdout
(case / 'issue949.patch').write_bytes(patch)
reverse = subprocess.run(['git', 'apply', '--reverse', '--check', str(case / 'issue949.patch')], cwd=repo, capture_output=True).returncode == 0
rows = trace_rows() if kind == 'jev' else []
tools = [row for row in rows if row.get('toolResult')]
validations = [row for row in tools if row['toolResult']['action'] == 'RUN_TESTS']
root_checks = [{'script': row['toolInput']['script'], 'exitCode': row['toolResult']['exitCode'], 'timedOut': row['toolResult']['timedOut'], 'durationMs': row['toolResult']['durationMs']} for row in validations] if kind == 'jev' else verification['independentRootChecks']
if kind == 'jev': root_checks += verification.get('supplementalRootChecks', [])
proxies = [json.loads(path.read_text()) for path in sorted(case.glob(worker + '-*.json'))]
full_test_logs = [path.with_suffix('.stdout.log') for path in case.glob('pnpm-*.json') if (metadata := json.loads(path.read_text())).get('originalArgs') == ['run', 'test'] and metadata.get('cwd') == str(repo)]
test_summaries = [summary for log in full_test_logs if log.exists() for summary in parse_test_summaries(log.read_text())]
test_counts = [sum(summary.values()) for summary in test_summaries]
unit = verification.get('formatTests', {}).get('counts', {})
regression = verification.get('baselineRegression', {}).get('counts', {})
checks = {
    'target_head_preserved': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=repo, text=True).strip() == initial['head'],
    'target_index_has_no_staged_edits': subprocess.run(['git', 'diff', '--cached', '--quiet'], cwd=repo).returncode == 0,
    'only_task_files_changed': changed == {'apps/web/lib/format.ts', 'apps/web/lib/format.test.ts'} and untracked == {'apps/web/lib/format.test.ts'},
    'reverse_patch_check_passed': reverse,
    'all_fifteen_acceptance_cases_pass': verification['acceptanceProbe']['exitCode'] == 0 and not verification['acceptanceProbe']['timedOut'] and verification['acceptanceProbe']['results'].get('passed') is True and len(verification['acceptanceProbe']['results'].get('results', [])) == 15,
    'new_formatter_tests_pass': unit.get('numTotalTests', 0) > 0 and unit.get('numFailedTests') == 0 and unit.get('numPendingTests') == 0 and verification.get('formatTests', {}).get('exitCode') == 0,
    'new_tests_detect_original_bug': regression.get('numFailedTests', 0) > 0 and regression.get('numPassedTests', 0) > 0 and verification.get('baselineRegression', {}).get('exitCode') == 1,
    'all_four_independent_root_checks_pass': {result['script'] for result in root_checks if result['exitCode'] == 0 and not result['timedOut']} == {'test', 'typecheck', 'lint', 'build'},
    'full_workspace_test_log_recorded': len(test_counts) == 4 and sum(test_counts) > 800,
    'one_successful_worker_process': len(proxies) == 1 and proxies[0].get('completed') is True and proxies[0].get('exitCode') == 0 and not proxies[0].get('outputLimitExceeded'),
}
summary = rows[-1].get('summary') if rows else None
terminal = (case / 'terminal.txt').read_text() if (case / 'terminal.txt').exists() else ''
status_match = re.search(r'Loop status: ([a-z_]+)', terminal)
loop_status = status_match.group(1) if status_match else None
if kind == 'jev' and summary:
    checks['completion_or_explicit_incomplete_status_recorded'] = loop_status is not None
    checks['iteration_and_call_limits_preserved'] = max(row['iteration'] for row in rows) <= 8 and summary['counts']['codexCalls'] <= 2 and summary['counts']['claudeCalls'] <= 2
    checks['fresh_current_generation_validation'] = summary['validation']['passed'] and summary['validation']['generation'] >= 1
receipt = {
    'case': name, 'trackingIssue': 31, 'task': manifest['task'], 'changedPaths': sorted(changed),
    'patchSha256': hashlib.sha256(patch).hexdigest(), 'checks': checks,
    'acceptedPatch': all(checks.values()), 'rootChecks': root_checks,
    'fullWorkspaceTests': sum(test_counts), 'fullTestSummaries': test_summaries, 'workerProcesses': proxies,
    'independentVerification': verification, 'cliSummary': summary, 'loopStatus': loop_status,
    'actionSequence': [{'iteration': row['iteration'], 'action': row['toolResult']['action'], 'script': row.get('toolInput', {}).get('script'), 'ok': row['toolResult']['ok']} for row in tools],
    'manualAlternatives': [item['action'] for row in rows for item in (row.get('approval') or {}).get('history', []) if item['kind'] == 'alternative'],
    'truncatedTraceStates': [{'iteration': row['iteration'], 'field': field} for row in rows for field in ['stateBefore', 'stateAfter'] if row.get(field, {}).get('truncated') is True],
}
(case / 'receipt.json').write_text(json.dumps(receipt, indent=2) + '\n')
print(json.dumps({'case': name, 'acceptedPatch': receipt['acceptedPatch'], 'checks': checks, 'fullWorkspaceTests': sum(test_counts)}, indent=2), flush=True)
raise SystemExit(0 if receipt['acceptedPatch'] else 1)
#!/usr/bin/env node
// Fixed direct control: prepare the same bounded evidence, then call the installed adapter once.
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const [entry, directory, worker, task] = process.argv.slice(2);
if (!entry || !directory || !['codex', 'claude'].includes(worker) || !task) throw new Error('Invalid direct-control arguments.');
const load = (name) => import(pathToFileURL(path.join(path.dirname(entry), name)));
const { inspectRepo } = await load('repo/inspect.js');
const { createInitialState } = await load('orchestration/loop.js');
const { executeCandidate } = await load('orchestration/execute.js');
const { buildWorkerContext } = await load('agents/context.js');
const { truncateText } = await load('limits.js');
const { redactSensitiveText } = await load('logging/trace.js');
const adapterModule = await load(`agents/${worker}.js`);
const save = (name, value) => writeFile(path.join(directory, name), redactSensitiveText(JSON.stringify(value, null, 2)) + '\n', { mode: 0o600 });
const controller = new AbortController();
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => controller.abort());
const startedAt = performance.now();
const snapshot = await inspectRepo(process.cwd());
const state = createInitialState(snapshot, task, worker, worker === 'codex' ? true : undefined);
const preparation = [];
const issue = await executeCandidate({ action: 'READ_ISSUE', tool: 'github_issue', input: { url: task } }, undefined, { signal: controller.signal });
if (!issue.ok || !issue.issue) throw new Error('Direct-control issue preparation failed.');
state.evidence.issue = issue.issue;
preparation.push({ action: 'READ_ISSUE', durationMs: issue.durationMs, ok: issue.ok });
let iteration = 2;
for (const file of ['AGENTS.md', 'CONTRIBUTING.md', 'CLAUDE.md'].filter((name) => snapshot.topLevelFiles.includes(name))) {
  const result = await executeCandidate({ action: 'READ_FILE', tool: 'read_file', input: { root: snapshot.root, path: file } });
  if (!result.ok) throw new Error('Direct-control instruction preparation failed.');
  state.filesRead.push(...result.files);
  state.evidence.findings.push({ iteration: iteration++, source: 'read', paths: result.files.slice(0, 8), excerpt: truncateText(result.output, 1_000) });
  preparation.push({ action: 'READ_FILE', path: file, durationMs: result.durationMs, ok: result.ok });
}
state.currentGoal = 'Validate the repository after inspection.';
const context = buildWorkerContext(state);
const preparationMs = Math.round(performance.now() - startedAt);
await save('direct-preparation.json', { preparationMs, preparation, context });
const request = { root: snapshot.root, task, context, ...(worker === 'codex' ? { networkAccess: true } : {}) };
await save('direct-request.json', request);
console.log('Prepared exact issue and repository instructions; beginning direct worker.');
const adapter = worker === 'codex' ? adapterModule.createCodexAdapter() : adapterModule.createClaudeAdapter();
const result = await adapter(request, { signal: controller.signal });
await save('direct-result.json', { ...result, preparationMs, activeBeforeValidationMs: Math.round(performance.now() - startedAt) });
console.log(JSON.stringify({ worker, ok: result.ok, exitCode: result.exitCode, workerMs: result.durationMs, timedOut: result.timedOut, cancelled: result.cancelled === true }));
process.exitCode = result.ok ? 0 : 1;
#!/usr/bin/env node
// Benchmark instrumentation only. Both paired runs use the same proxy.
import { spawn } from 'node:child_process';
import { closeSync, openSync, writeSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const [command, ...originalArgs] = process.argv.slice(2);
if (!['codex', 'claude', 'pnpm'].includes(command)) throw new Error('Unknown benchmark command.');
const directory = process.env.BENCH_CASE_DIR;
const entry = process.env.BENCH_PACKAGE_ENTRY;
const executable = process.env[`BENCH_REAL_${command.toUpperCase()}`];
if (!directory || !entry || !executable) throw new Error('Missing benchmark configuration.');
const { redactSensitiveText } = await import(pathToFileURL(path.join(path.dirname(entry), 'logging/trace.js')));
const prefix = path.join(directory, `${command}-${process.pid}`);
const args = [...originalArgs];
if (command === 'codex') args.splice(args.indexOf('--'), 0, '--json');
if (command === 'claude') {
  args[args.indexOf('--output-format') + 1] = 'stream-json';
  args[args.indexOf('--model') + 1] = 'claude-sonnet-5-5';
  args.splice(args.indexOf('--'), 0, '--verbose');
}
const startedAt = performance.now();
const metadata = {
  command, originalArgs, args, cwd: process.cwd(),
  startedAt: new Date().toISOString(), instrumentation: 'structured output; identical in both setups',
};
const save = () => writeFileSync(`${prefix}.json`, redactSensitiveText(JSON.stringify(metadata, null, 2)) + '\n', { mode: 0o600 });
save();
const stdoutFile = openSync(`${prefix}.${command === 'pnpm' ? 'stdout.log' : 'events.jsonl'}`, 'wx', 0o600);
const stderrFile = openSync(`${prefix}.stderr.log`, 'wx', 0o600);
const environment = { ...process.env };
// Evaluation credentials are never needed by the worker or validation process.
for (const name of ['AI_GATEWAY_API_KEY', 'OPENROUTER_API_KEY', 'OPENROUTE_API_KEY', 'TYPESAFE_API_KEY', 'TYPESAFE_AI_API_KEY']) delete environment[name];
const child = spawn(executable, args, { stdio: ['ignore', 'pipe', 'pipe'], env: environment });
let pending = '';
let stdoutBytes = 0;
let stderrBytes = 0;
let outputLimitExceeded = false;
let completed = command === 'pnpm';
const servedModels = new Set();
const maximumBytes = 8 * 1024 * 1024;
function log(file, text, stream) {
  const safe = redactSensitiveText(text);
  const bytes = Buffer.byteLength(safe);
  if (stream === 'stdout') stdoutBytes += bytes;
  else stderrBytes += bytes;
  if (stdoutBytes > maximumBytes || stderrBytes > maximumBytes) {
    outputLimitExceeded = true;
    child.kill('SIGTERM');
    return;
  }
  writeSync(file, safe);
}
function usage(value) {
  if (!value || typeof value !== 'object') return undefined;
  const names = ['input_tokens', 'cached_input_tokens', 'output_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens'];
  return Object.fromEntries(names.filter((name) => Number.isFinite(value[name]) && value[name] >= 0).map((name) => [name, value[name]]));
}
function eventLine(line) {
  log(stdoutFile, line + '\n', 'stdout');
  let event;
  try { event = JSON.parse(line); } catch { return; }
  if (command === 'codex') {
    if (event.type === 'item.completed' && event.item?.type === 'agent_message') {
      process.stdout.write(redactSensitiveText(event.item.text) + '\n');
    }
    if (event.type === 'turn.completed') {
      completed = true;
      metadata.usage = usage(event.usage);
    }
    if (event.type === 'turn.failed' || event.type === 'error') metadata.reportedFailure = true;
  } else {
    if (typeof event.message?.model === 'string') servedModels.add(event.message.model);
    if (event.type === 'result') {
      completed = !event.is_error;
      metadata.reportedFailure = event.is_error === true;
      metadata.usage = usage(event.usage);
      metadata.turns = event.num_turns;
      if (Number.isFinite(event.total_cost_usd) && event.total_cost_usd >= 0) metadata.reportedCostUsd = event.total_cost_usd;
      if (typeof event.result === 'string') process.stdout.write(redactSensitiveText(event.result) + '\n');
    }
  }
}
child.stdout.on('data', (chunk) => {
  if (command === 'pnpm') {
    log(stdoutFile, chunk.toString(), 'stdout');
    process.stdout.write(chunk);
    return;
  }
  pending += chunk.toString();
  while (pending.includes('\n')) {
    const end = pending.indexOf('\n');
    const line = pending.slice(0, end);
    pending = pending.slice(end + 1);
    if (line.trim()) eventLine(line);
  }
  if (Buffer.byteLength(pending) > maximumBytes) {
    outputLimitExceeded = true;
    child.kill('SIGTERM');
  }
});
child.stderr.on('data', (chunk) => {
  log(stderrFile, chunk.toString(), 'stderr');
  process.stderr.write(redactSensitiveText(chunk.toString()));
});
child.on('error', () => {
  metadata.spawnFailed = true;
  process.stderr.write('Benchmark child could not start.\n');
});
child.on('close', (exitCode, signal) => {
  if (pending.trim()) eventLine(pending);
  Object.assign(metadata, {
    exitCode, signal, durationMs: Math.round(performance.now() - startedAt),
    endedAt: new Date().toISOString(), completed, outputLimitExceeded,
    stdoutBytes, stderrBytes, servedModels: [...servedModels],
  });
  save();
  closeSync(stdoutFile);
  closeSync(stderrFile);
  process.exitCode = outputLimitExceeded || !completed ? 1 : (exitCode ?? 1);
});
# Matched worker benchmark: issue #31

Recorded on 2026-10-13 (America/New_York) for [issue #31](https://github.com/petercr/jev-orchestrator/issues/31). The task was [TrusTrove #949](https://github.com/TrusTrove/TrusTrove-app/issues/949): fix short-address formatting and add production boundary tests.

The twelve scheduled observations are complete. Nine patches passed the full acceptance gate; eight workflows completed successfully. The two Codex setups each produced two accepted patches and one incorrect new test. All six Claude implementations passed the functional probes and new unit tests; one standalone build timed out, and one JEV loop exhausted its iteration budget after a rejected evaluation. These results do not establish a general speed or quality advantage for JEV.

The worker means across all three attempts were 68.7 seconds with JEV versus 70.3 seconds directly for Codex, and 16.4 versus 15.8 seconds for Claude. Validation dominated active time and varied between observations. Successful-only statistics below retain their smaller sample counts; failed observations were never replaced.

## Frozen setup

| Setting | Value |
| --- | --- |
| Runtime package | `jev-orchestrator@0.2.0`, built from `dbfa2e51ff37d525aac04beb00d27031e5c09d31` |
| Packed archive SHA-256 | `9cb222ff9b96de2f7ed178e02acd9f66f36eb58160a728a961b81ed76a53362e` |
| Target baseline | `6cae96e13e950a9e932130ef1a7aebbcddf9c58e` |
| Task input | Exact public issue URL, identical in every run |
| Evaluator | Direct TypeSafe, requested/served `jev-1.13.0` |
| Codex | CLI `0.162.1`, `gpt-5.6-terra`, high effort |
| Claude | CLI `2.1.296`, explicit requested/served `claude-sonnet-5-5`, medium effort |
| Environment | Node.js `24.21.0`, target pnpm `10.30.3`, source pnpm `11.19.0` |
| Limits | Eight JEV iterations, two calls per adapter; one implementation attempt per observation; 15-minute worker timeout; 120-second validation timeout |

Every observation used a new external clone and independently copied dependencies installed from the frozen lockfile. A separate pristine baseline passed typecheck, build, lint, and 800 tests while reproducing the defect at every string length from 1 through 10. Dependency setup and baseline checks were outside measured worker time.

The direct controls used the same installed adapters and received byte-for-byte identical bounded worker contexts: fetched issue evidence and contributor instructions. Their preparation was timed separately. Original and instrumented worker argument arrays match within all six pairs after replacing the selected repository path with a placeholder. Output instrumentation was identical within each pair. This controls for preparation and tool access; it does not measure an unrestricted standalone agent discovering the task itself.

Codex retained `workspace-write`, `--ask-for-approval never`, explicit command networking, ephemeral execution, and ignored user configuration/rules. Claude retained restricted mode, only file tools plus the private bounded rename tool, empty setting sources, explicit settings, strict MCP configuration, and no session persistence. Project test/typecheck/lint/build commands ran outside worker calls. Codex and Claude have different models and tool sets; comparisons are made within each worker pair.

## Observed exceptions

- `codex-standalone-2` implemented the formatter correctly but expected an 11-character input to remain unchanged. Its new test and root test command failed. The functional probe passed; the patch was not accepted.
- `codex-jev-3` implemented the formatter correctly but expected the wrong trailing four characters for an 11-character input. Independent tests failed. The loop offered a bounded repair; the operator stopped at iteration five to preserve the fixed first-attempt protocol. Remaining typecheck/lint/build checks ran as separate post-stop audits. Their timings are explicit and do not modify CLI metrics, state, approvals, or completion.
- `claude-standalone-2` passed tests, typecheck, lint, and functional/regression probes, but build hit the unchanged 120-second timeout while collecting build traces. The process group was confirmed gone. Build remains unverified for this observation; it was not rerun or given a larger budget.
- `claude-jev-2` rejected an evaluation distribution totaling `0.99` under the unchanged `0.001` tolerance. Explicit continuation consumed the last iteration on build. All four current-generation checks passed, but completion approval had no remaining iteration. The loop returned `iteration_limit` and exit code 1, retaining the patch and evidence.

All six JEV runs required a manual worker alternative. The four completed JEV loops also required a manual `FINISH` alternative followed by approval after acceptance review. No worker retries occurred. One evaluation failure and one explicit recovery were recorded. Upstream HTTP retries and worker-internal provider retries are unavailable and are not inferred. Confidence thresholds, worker selection, networking, call limits, independent validation, and completion rules were preserved.

## Per-run and aggregate timings

