// Verify one common pristine baseline, outside every worker observation.
import { cpSync, existsSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { commandOutput, isMain, loadManifest, requireCondition, runLogged, writeJson } from './lib.mjs';

export async function baseline(directory) {
  const { root, manifest } = loadManifest(directory);
  const seed = path.join(root, manifest.runOrder[0], 'repo');
  const repo = path.join(root, 'baseline');
  commandOutput(['git', 'clone', '--quiet', '--no-hardlinks', seed, repo], root);
  const packages = commandOutput(['git', 'ls-files', '-z'], repo).split('\0');
  const modulePaths = new Set(['node_modules', ...packages.filter((name) => name.endsWith('package.json')).map((name) => path.join(path.dirname(name), 'node_modules'))]);
  for (const relative of modulePaths) if (existsSync(path.join(seed, relative))) cpSync(path.join(seed, relative), path.join(repo, relative), { recursive: true, verbatimSymlinks: true });
  const environment = { ...process.env, NEXT_TELEMETRY_DISABLED: '1' };
  const checks = [];
  for (const script of ['typecheck', 'build', 'lint', 'test']) {
    const result = { script, ...await runLogged(['pnpm', 'run', script], repo, path.join(root, 'baseline-' + script + '.log'), { environment }) };
    checks.push(result);
    writeJson(path.join(root, 'baseline-validation.json'), checks);
    console.log(JSON.stringify(result));
  }
  // tsx is part of the pinned source toolchain; Node 22 need not strip types natively.
  const probe = `import {pathToFileURL} from 'node:url';
const {truncateAddress}=await import(pathToFileURL(process.argv[1]));
const failures=Array.from({length:10},(_,i)=>'ABCDEFGHIJ'.slice(0,i+1)).filter(text=>truncateAddress(text)!==text).map(text=>text.length);
console.log(JSON.stringify({shortLengthsFailing:failures}));
process.exitCode=failures.length===10?0:1;`;
  const result = commandOutput([process.execPath, '--import', path.join(manifest.sourceCheckout, 'node_modules/tsx/dist/loader.mjs'), '--input-type=module', '-e', probe, path.join(repo, 'apps/web/lib/format.ts')], repo);
  writeFileSync(path.join(root, 'baseline-bug.json'), result);
  console.log(result.trim());
  requireCondition(checks.every((check) => check.exitCode === 0 && !check.timedOut && !check.outputLimitExceeded), 'A baseline check failed.');
}

if (isMain(import.meta.url)) await baseline(process.argv[2]);

// Pure receipt parsing. Reporting never authorizes a worker or completion.
export function parseTestSummaries(text) {
  return [...text.matchAll(/^\s*Tests\s+(.+)$/gm)].map((match) => Object.fromEntries(
    [...match[1].matchAll(/(\d+) (passed|failed|skipped|todo)/g)].map((count) => [count[2], Number(count[1])]),
  )).filter((counts) => Object.keys(counts).length);
}

export function parseAcceptance(text) {
  const line = text.split('\n').find((line) => line.startsWith('{"fixtureLength":'));
  return line ? JSON.parse(line) : { passed: false };
}

export function directStatus(worker, receipt) {
  if (worker.cancelled) return 'cancelled';
  if (worker.timedOut) return 'timed_out';
  if (!worker.ok) return 'worker_failed';
  if (receipt.rootChecks.some((check) => check.timedOut)) return 'validation_timed_out';
  if (receipt.rootChecks.some((check) => check.exitCode !== 0 || check.timedOut)) return 'validation_failed';
  return receipt.acceptedPatch ? 'ready_for_review' : 'acceptance_failed';
}

export function comparisonOutcome(status, checks) {
  if (status === 'iteration_limit') return status;
  if (checks.some((check) => check.timedOut)) return 'validation_timed_out';
  if (checks.some((check) => check.exitCode !== 0)) return 'validation_failed';
  return status;
}

export function timingStatistics(values) {
  if (!values.length) return { n: 0, mean: null, median: null, min: null, max: null, sampleStandardDeviation: null };
  const sorted = [...values].sort((left, right) => left - right);
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
  const middle = Math.floor(values.length / 2);
  return {
    n: values.length, mean, median: values.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2,
    min: sorted[0], max: sorted.at(-1),
    sampleStandardDeviation: values.length >= 2 ? Math.sqrt(values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (values.length - 1)) : null,
  };
}

