/**
 * Truncates a blockchain address for display, showing the first 6 and last 4 characters.
 *
 * @param addr - The full address string to truncate.
 * @returns The truncated address with ellipsis, or an empty string if the input is falsy.
 *
 * @example
 * ```ts
 * truncateAddress("GBBD47IF6LZ72Y..."); // "GBBD47...Y..."
 * ```
 */
export function truncateAddress(addr?: string): string {
  if (!addr) return "";
  if (addr.length <= 10) return addr;
  return `${addr.slice(0, 6)}...${addr.slice(-4)}`;
}
import { describe, expect, it } from "vitest";
import { truncateAddress } from "./format";

describe("truncateAddress", () => {
  it("truncates a 56-character Stellar address", () => {
    const address = "GAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWHF";

    expect(truncateAddress(address)).toBe("GAAAAA...AWHF");
  });

  it.each([
    ["", ""],
    [undefined, ""],
  ])("returns an empty string for %j", (address, expected) => {
    expect(truncateAddress(address)).toBe(expected);
  });

  it.each([
    ["A", "A"],
    ["1234567890", "1234567890"],
    ["12345678901", "123456...8901"],
  ])("formats an address of length %s correctly", (address, expected) => {
    expect(truncateAddress(address)).toBe(expected);
  });
});

