text(await tools.exec_command({cmd:"node --input-type=module - '"+root+"' <<'NODE'
import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {isDeepStrictEqual} from 'node:util';
import path from 'node:path';
import {auditCase} from './scripts/benchmarks/audit.mjs';
import {aggregateRun} from './scripts/benchmarks/report.mjs';
import {fileHash,fingerprint,readTraceRows} from './scripts/benchmarks/lib.mjs';
const root=process.argv[2],name='codex-jev-1',directory=path.join(root,name);
const manifest=JSON.parse(readFileSync(path.join(root,'manifest.json')));
const receipt=JSON.parse(readFileSync(path.join(directory,'receipt.json')));
const timings=JSON.parse(readFileSync(path.join(directory,'timings.json')));
const rows=readTraceRows(path.join(directory,'repo'));
const checks=auditCase(name,receipt,rows);
const before=JSON.parse(readFileSync(path.join(root,'original-before.json')));
for(const [repo,initial] of Object.entries(before))checks['protected_checkout_preserved:'+repo]=isDeepStrictEqual(fingerprint(repo),initial);
checks.frozen_harness_preserved=Object.entries(manifest.harnessHashes).every(([name,expected])=>fileHash(path.join(root,'harness',name))===expected);
checks.packed_archive_preserved=fileHash(path.join(root,'jev-orchestrator-0.2.0.tgz'))===manifest.packageSha256;
checks.eight_actual_approvals=timings.operatorInputs.filter(input=>input.choice==='approve').length===8;
checks.one_worker_no_retry=receipt.cliSummary.counts.workerCalls===1&&receipt.cliSummary.counts.adapterRetries===0;
