const root=load("liveRoot");
text(await tools.exec_command({cmd:"node --input-type=module - '"+root+"' <<'NODE'
import {readFileSync,writeFileSync} from 'node:fs';
import path from 'node:path';
const root=process.argv[2];
const file=path.join(root,'LIVE-SUMMARY.json');
const summary=JSON.parse(readFileSync(file));
const receipt=JSON.parse(readFileSync(path.join(root,'codex-jev-1/receipt.json')));
const counts=receipt.cliSummary.counts;
summary.audit.checks.one_worker_no_retry=counts.codexCalls===1&&counts.claudeCalls===0&&counts.workerRetries===0&&receipt.workerProcesses.length===1;
summary.audit.passed=Object.values(summary.audit.checks).every(Boolean);
writeFileSync(file,JSON.stringify(summary,null,2)+'\n',{mode:0o600});
const run=summary.observation;
const lines=['# Node benchmark harness live smoke — issues #35 and #36','',`Recorded ${new Date().toISOString()}. One live JEV + Codex observation on the pinned TrusTrove #949 task and baseline.`,`This is a functional smoke check; it does not establish a timing advantage.`, '', '| Result | Value |','| --- | --- |',`| Loop | ${receipt.loopStatus}, exit ${run.exitCode}, 8 iterations |`,`| Worker | Codex gpt-5.6-terra, high effort, workspace-write, explicit networking |`,`| Worker calls / retries | ${counts.codexCalls} / ${counts.workerRetries} |`,`| Worker time | ${(run.workerMs/1000).toFixed(3)} seconds |`,`| Independent validation time | ${(run.validationMs/1000).toFixed(3)} seconds |`,`| Active time | ${(run.activeMs/1000).toFixed(3)} seconds |`,`| Prompt wait | ${(run.promptWaitMs/1000).toFixed(3)} seconds |`,`| Workspace tests | ${receipt.fullWorkspaceTests} passing |`,`| Independent root checks | test, typecheck, lint, build passed in generation 1 |`,`| Acceptance | 15 cases passed; new tests detect the original short-input bug |`,`| Audit | ${Object.keys(summary.audit.checks).length} checks passed |`, '', 'The issue and contributor instructions were read before delegation. Ambiguous delegation and completion were resolved through reviewed alternatives and individual approvals. No validation, failed worker, or evaluation was retried. The patch changes only apps/web/lib/format.ts and apps/web/lib/format.test.ts. Protected checkouts, frozen harness files, and the packed archive are preserved.','',`An initial launch at ${summary.failedLauncherEvidence} exited before JEV/worker execution because the pnpm package symlink was unresolved. That attempt remains recorded in live-launch-diagnostic.json and timings.json. prepare.mjs now uses realpathSync for packageEntry; the regression fixture exercises the symlink and CLI entry-point check. A fresh corrected dataset was prepared. The successful baseline receipts from the same session are referenced in baseline-reuse.json.`, '', 'Receipts and full logs are under codex-jev-1; LIVE-SUMMARY.json contains the phase timings, counters, actual reported usage, and audit results. Missing served Codex model versions and costs are not inferred.',''];
writeFileSync(path.join(root,'LIVE-REPORT.md'),lines.join('\n'));
console.log(JSON.stringify({loopStatus:receipt.loopStatus,exitCode:run.exitCode,workerCalls:counts.codexCalls,workerRetries:counts.workerRetries,workspaceTests:receipt.fullWorkspaceTests,auditPassed:summary.audit.passed,auditChecks:Object.keys(summary.audit.checks).length,report:path.join(root,'LIVE-REPORT.md')},null,2));
if(!summary.audit.passed)process.exitCode=1;
NODE",max_output_tokens:2400}));
