import {readFileSync,readdirSync,statSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import path from 'node:path';
const names=['AI_GATEWAY_API_KEY','OPENROUTER_API_KEY','OPENROUTE_API_KEY','TYPESAFE_API_KEY','TYPESAFE_AI_API_KEY'];
const values=names.map(name=>process.env[name]).filter(Boolean);
const extensions=new Set(['.json','.jsonl','.log','.txt','.md','.mjs','.patch']);
const files=[];
function scan(directory,depth=0){for(const entry of readdirSync(directory,{withFileTypes:true})){if(['repo','consumer','baseline','regression-web','node_modules'].includes(entry.name))continue;const file=path.join(directory,entry.name);if(entry.isDirectory()&&depth<2)scan(file,depth+1);else if(entry.isFile()&&extensions.has(path.extname(file))&&statSync(file).size<=8*1024*1024)files.push(file);}}
for(const directory of process.argv.slice(2))scan(directory);
const changed=spawnSync('git',['status','--porcelain','-z'],{encoding:'utf8'}).stdout.split('\0').filter(row=>row&&!row.startsWith(' D ')).map(row=>row.slice(3));
